<script>
document.addEventListener('click', function (e) {
  var t = e.target.closest('[data-hub-rule]'); if (!t) return;
  var on = t.classList.contains('on');
  CS.post(CS.admin, 'rule_status', { id: t.getAttribute('data-hub-rule'), status: on ? 'published' : 'paused' }).then(function (j) { SL.toast(j.success ? (on ? 'Rule on' : 'Rule paused') : j.message, !j.success); if (!j.success) t.classList.toggle('on'); });
});
</script>
